@component
export class Position { x: f32 = 0; y: f32 = 0; }
@component
export class Velocity { x: f32 = 0; y: f32 = 0; }
@system
export function integrate(q: Query<[Write<Position>, Read<Velocity>]>, dt: f32): void {
 for(const [p,v] of q){
  const one:Scalar=1, negative:Scalar=-0; let amount:Scalar=1.25e-2; const largest:Scalar=3.4028234663852886e38; const tiny:Scalar=1.401298464324817e-45; const inferred=1.25e-2; amount*=one; amount/=dt; amount-=negative; amount=literalGain(amount); p.x=amount;
  p.y += v.y * dt;
 }
}

function scaled(v:f32,dt:f32):f32{return v*dt;}
function unused(v:i32):i32{return v+1;}
class Box {value:i32=1;}

function literalGain(v:Scalar):Scalar{const unit:Scalar=1; let current:Scalar=-0; current+=v; return current;}

